    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    create(&mut h, "other", json!({}));
    send_batch(&mut h, "q", json!([{"Id": "a", "Body": "x"}, {"Id": "b", "Body": "y"}]));
    h.ok(json!({"Command": "SendMessage", "QueueName": "other", "Body": "o"}));
    let handles: Vec<Value> = receive(&mut h, "q", 2).iter().map(|m| m["ReceiptHandle"].clone()).collect();
    let foreign = receive(&mut h, "other", 1)[0]["ReceiptHandle"].clone();
    let r = delete_batch(
        &mut h,
        "q",
        json!([{"Id": "1", "ReceiptHandle": handles[0]}, {"Id": "2", "ReceiptHandle": handles[0]},
               {"Id": "3", "ReceiptHandle": "r-99"}, {"Id": "4"}, {"Id": "5", "ReceiptHandle": 7},
               {"Id": "6", "ReceiptHandle": foreign}, {"Id": "7", "ReceiptHandle": handles[1]}]),
    );
    assert_eq!(r["Successful"], json!([{"Id": "1"}, {"Id": "7"}]));
    assert_eq!(
        codes(&r),
        [("2", "ReceiptHandleExpired"), ("3", "ReceiptHandleInvalid"), ("4", "MissingParameter"),
         ("5", "InvalidParameterValue"), ("6", "ReceiptHandleExpired")]
    );
    let counts = h.ok(json!({"Command": "GetQueueAttributes", "QueueName": "q"}))["Counts"].clone();
    assert_eq!(counts, json!({"Visible": 0, "InFlight": 0, "Delayed": 0}));
}

#[test]
fn batch_request_rules_fail_the_whole_request_without_effect() {
    let mut h = Harness::new();
    create(&mut h, "q", json!({}));
    let long_id = "i".repeat(81);
    let cases = [
        (json!([]), "EmptyBatchRequest"),
        (json!((0..11).map(|i| json!({"Id": format!("{i}"), "Body": "x"})).collect::<Vec<_>>()), "TooManyEntriesInBatchRequest"),
        (json!([{"Id": "a", "Body": "x"}, 5]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Id": null, "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Id": 1, "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Id": "", "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Id": "a b", "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Id": long_id, "Body": "x"}]), "InvalidBatchEntryId"),
        (json!([{"Id": "a", "Body": "x"}, {"Id": "a", "Body": "y"}]), "BatchEntryIdsNotDistinct"),
        (json!([{"Id": "a"}, {"Id": "a"}, 3]), "InvalidBatchEntryId"),
    ];
    for (entries, code) in cases {
        let r = send_batch(&mut h, "q", entries.clone());
        assert_eq!(r["error"]["code"], code, "{entries}");
        let r = delete_batch(&mut h, "q", entries.clone());
        assert_eq!(r["error"]["code"], code, "{entries}");
    }
    let ok = send_batch(&mut h, "q", json!([{"Id": "x".repeat(80), "Body": "m"}]));
    assert_eq!(ok["Successful"][0]["MessageId"], "m-1");
    let ten: Vec<Value> = (0..10).map(|i| json!({"Id": format!("{i}"), "Body": "x"})).collect();
    assert_eq!(send_batch(&mut h, "q", json!(ten))["Successful"].as_array().unwrap().len(), 10);
}

#[test]
fn batch_checks_come_in_spec_order() {
    let mut h = Harness::new();
    let batch = |c: &str, q: Value, e: Value| json!({"Command": c, "QueueName": q, "Entries": e});
    for c in ["SendMessageBatch", "DeleteMessageBatch"] {
        assert_eq!(h.err(json!({"Command": c, "Entries": []})), "MissingParameter");
        assert_eq!(h.err(json!({"Command": c, "QueueName": "q"})), "MissingParameter");
        assert_eq!(h.err(batch(c, json!("q"), json!({}))), "InvalidParameterValue");
        assert_eq!(h.err(batch(c, json!(1), json!([]))), "InvalidParameterValue");
        assert_eq!(h.err(batch(c, json!("q"), json!([]))), "QueueDoesNotExist");
    }
}

